<script>
  import Listen from '$lib/Listen.svelte';
  import { speech } from '$lib/speech.js';
  import { onDestroy } from 'svelte';
  import { scenes, capture, getCard, matchesQuestion } from '$lib/demo.js';
  let scene = $state('weather');
  let asked = $state(false);
  let helper = $state('');
  let cards = $state([]);
  let completed = $state([]);
  let visited = $state([]);
  let view = $state('story');
  let input = $state('');
  let feedback = $state('');
  let revealed = $state(false);
  let reviewed = $state([]);
  let queue = $state([]);
  let audioMessage = $state('');
  let item = $derived(scenes[scene]);
  let currentCard = $derived(queue.length ? getCard(queue[0]) : null);
  function stopAudio() { speech.stop(); }
  onDestroy(stopAudio);
  function choose(next) { stopAudio(); scene = next; asked = false; helper = ''; input = ''; feedback = ''; audioMessage = ''; view = 'story'; }
  function ask() { asked = true; cards = capture(cards, scene); if (!visited.includes(scene)) visited = [...visited, scene]; }
  function help(next) { helper = next; if (next === 'nante') cards = capture(cards, scene, 'question'); }
  function tryJapanese() {
    if (!matchesQuestion(scene, input)) { feedback = 'Not recognised in this guided demo yet. Try the phrase below in Japanese or romaji. Hints count too!'; return; }
    ask(); cards = capture(cards, scene, 'question');
    if (!completed.includes(scene)) completed = [...completed, scene];
    feedback = 'Quest complete! You just used Japanese for an everyday request.';
  }
  function review() { stopAudio(); queue = cards.filter(id => !reviewed.includes(id)); revealed = false; view = 'review'; audioMessage = ''; }
  function rate(remembered) {
    const id = queue[0];
    queue = remembered ? queue.slice(1) : [...queue.slice(1), id];
    if (remembered) reviewed = [...reviewed, id];
    revealed = false; stopAudio(); audioMessage = '';
  }
  function reset() { cards = []; completed = []; visited = []; reviewed = []; queue = []; choose('weather'); }

</script>

<svelte:head><title>Marta’s first adventure · Alexa-chan</title><meta name="description" content="An interactive demo: weather, your calendar, your first Japanese words, and memory cards."/></svelte:head>

<div class="world">
  <header><a class="brand" href="/">ア <span>alexa-chan</span></a><span class="badge">INTERACTIVE DEMO / SAMPLE DATA</span><button class="text-button" onclick={reset}>Start over ↺</button></header>
  <main>
    <section class="intro"><div><p class="eyebrow">BRUSSELS, 08:12 · THE FIRST CHAPTER</p><h1>Her day begins.<br/><em>So does her Japanese.</em></h1><p>Marta speaks English. She isn’t here for a lesson.<br/>She just wants to get ready for her day.</p></div><div class="passport"><span class="avatar">マ</span><div><b>Marta</b><span>Beginner · curious, no pressure</span><small>{cards.length} memories collected · {completed.length}/2 quests</small></div></div></section>
    <nav aria-label="Demo chapters"><button class:active={view === 'story' && scene === 'weather'} onclick={() => choose('weather')}><span>01</span> The weather {visited.includes('weather') ? '✓' : ''}</button><button class:active={view === 'story' && scene === 'calendar'} onclick={() => choose('calendar')}><span>02</span> Your calendar {visited.includes('calendar') ? '✓' : ''}</button><button class:active={view === 'review'} onclick={review}><span>03</span> Your memories <b>{cards.length}</b></button></nav>
    {#if view === 'story'}
      <div class="board"><section class="art" style={`--scene: url('/images/${item.image}')`}><span class="stamp">MISSION {scene === 'weather' ? '01' : '02'} / 日常</span><div class="art-copy"><span class="large-icon" aria-hidden="true">{item.icon}</span><h2>{item.title}</h2>{#if scene === 'weather'}<p>18° <span>Brussels · sunny spells</span></p>{:else}<div class="appointment"><b>09:30</b> Team meeting</div><div class="appointment"><b>14:00</b> Coffee with Lea</div>{/if}<small>Sample scenario · no account connected</small></div></section>
      <section class="conversation" aria-label="Conversation with Alexa-chan"><div class="section-title"><span>A CONVERSATION, NOT A LESSON</span><span class="signal">●</span></div>
        {#if !asked}<div class="start"><span class="speech-symbol">“</span><h2>A question you already ask.</h2><p>Play as Marta: start in English. Japanese appears naturally in the answer.</p><button class="primary" onclick={ask}>« {item.prompt} » ↗</button><small>Click to simulate the request · no microphone</small><Listen text={item.prompt} label="Listen to the request" /></div>
        {:else}<div class="user-bubble">{item.prompt}</div><div class="response" aria-live="polite"><span class="speaker">ア / ALEXA-CHAN</span><p>{item.answer}</p><h2 lang="ja">{item.jp}</h2><p class="romaji">{item.romaji}</p><Listen text={item.answer} label="Listen in English" /><Listen text={item.jp} lang="ja-JP" label="Listen in Japanese" /></div>
        <p class="gentle">You can leave it there. Or follow your curiosity.</p><div class="helpers">{#each [['ike', 'Iké', 'Meaning'], ['motto', 'Motto', 'Explain'], ['nante', 'Nanté', 'My turn']] as [key, label, hint]}<button class:selected={helper === key} aria-pressed={helper === key} onclick={() => help(key)}><b>{label}</b><span>{hint}</span></button>{/each}</div>
        {#if helper}<div class="helper-answer" aria-live="polite">{#if helper === 'ike'}<span>THE MEANING</span><p>{item.translation}</p><Listen text={item.translation} label="Listen to the meaning" />{:else if helper === 'motto'}<span>A LITTLE DEEPER</span><p>{item.translation}</p><Listen text={item.translation} label="Listen to the meaning" /><p>{item.detail}</p><Listen text={item.detail} label="Listen to the explanation" />{:else}<span>HOW DO I ASK THAT?</span><h3 lang="ja">{item.question}</h3><p class="romaji">{item.questionRomaji}</p><Listen text={item.question} lang="ja-JP" label="Listen to the question" /><p>{item.questionMeaning}</p><Listen text={item.questionMeaning} label="Listen to its meaning" />{/if}</div>{/if}
        <details class="quest" open={helper === 'nante'}><summary>↗ Optional mini quest: ask it in Japanese</summary><p>A hint is enough to get started. No pronunciation score.</p><form onsubmit={(event) => { event.preventDefault(); tryJapanese(); }}><label for="japanese">Your question, in Japanese or romaji</label><div class="input-row"><input id="japanese" bind:value={input} placeholder={item.questionRomaji} autocomplete="off"/><button class="primary" disabled={!input.trim()}>Try it ↗</button></div></form><button class="text-button" onclick={() => { input = item.questionRomaji; help('nante'); }}>Use a hint : {item.questionRomaji}</button><p role="status" class:success={completed.includes(scene)}>{feedback}</p>{#if feedback}<Listen text={feedback} label="Listen to feedback" />{/if}</details>
        <button class="next" onclick={() => scene === 'weather' ? choose('calendar') : review()}>{scene === 'weather' ? 'Continue my day →' : 'Review my memories →'}</button>{/if}
        <p class="audio-message" role="status">{audioMessage}</p>
      </section></div>
    {:else}<div class="board review-board"><section class="art memory"><span class="stamp">YOUR MEMORIES / 記憶</span><div class="art-copy"><h2>You’ve met these words before.</h2><p>Now, see what comes back.</p><small>{reviewed.length} cards recalled during this visit</small></div></section><section class="conversation"><div class="section-title"><span>YOUR COLLECTION · {cards.length} CARDS</span><span>{queue.length} left</span></div>{#if currentCard}<div class="flashcard"><span class="eyebrow">DO YOU REMEMBER THE MEANING?</span><h2 lang="ja">{currentCard.jp}</h2><p class="romaji">{currentCard.romaji}</p><Listen text={currentCard.jp} lang="ja-JP" label="Listen in Japanese" />{#if revealed}<div class="translation">{currentCard.en}</div><Listen text={currentCard.en} label="Listen to the meaning" />{:else}<button class="primary" onclick={() => revealed = true}>Reveal the memory ↗</button>{/if}</div>{#if revealed}<div class="ratings"><button onclick={() => rate(false)}>Review again <small>Returns in this session</small></button><button onclick={() => rate(true)}>I remember ✓ <small>Done for this demo</small></button></div>{/if}{:else}<div class="start"><span class="speech-symbol">{cards.length ? '✓' : 'あ'}</span><h2>{cards.length ? 'A small step. A big beginning.' : 'Start with a conversation.'}</h2><p>{cards.length ? 'Marta came to plan her day. She leaves with a little Japanese.' : 'Weather and calendar phrases become your cards as you explore the demo.'}</p><button class="primary" onclick={() => choose('weather')}>Back to your day ↗</button></div>{/if}<p class="gentle">Demo review lasts for this visit. The legacy dashboard has a separate spaced-repetition mode.</p><p role="status">{audioMessage}</p></section></div>{/if}
    <footer><span>Guided prototype with scripted responses · not a live Alexa+ connection.</span><a href="/">Open the dashboard ↗</a></footer>
  </main>
</div>

<style>
  :global(body){margin:0;background:#e8eeeb;color:#202d30;font-family:Arial,sans-serif}:global(*){box-sizing:border-box}button,input{font:inherit}button{cursor:pointer}button:focus-visible,a:focus-visible,input:focus-visible,summary:focus-visible{outline:3px solid #d0382c;outline-offset:4px}button:disabled{opacity:.45;cursor:default}.world{max-width:1440px;margin:auto;padding:0 48px}header{display:flex;align-items:center;justify-content:space-between;gap:18px;padding:24px 0;border-bottom:1px solid #b6c6c5}.brand{font-size:28px;font-weight:bold;text-decoration:none;color:#ce352c}.brand span{font-size:20px;color:#202d30}.badge,.eyebrow,.stamp,.section-title,.speaker{font:10px/1.6 monospace;letter-spacing:1.5px}.badge{padding:7px 12px;border:1px solid #a6babc}.text-button{border:0;background:none;color:#994138;padding:10px 0;font-size:12px}.intro{display:flex;justify-content:space-between;align-items:end;gap:30px;padding:40px 0 28px}h1{font-size:clamp(32px,4vw,56px);line-height:1.05;letter-spacing:-2px;margin:15px 0}h1 em{font-style:normal;color:#ce352c}p{font-size:14px;line-height:1.7;color:#4a6166}.passport{display:flex;align-items:center;gap:14px;padding-bottom:10px}.avatar{display:grid;place-items:center;width:56px;height:64px;background:#bcd5d9;font-size:30px;border:1px solid #9bbec3;transform:rotate(-6deg)}.passport b,.passport span:not(.avatar),.passport small{display:block}.passport b{font-size:20px}.passport span:not(.avatar){font-size:12px;margin:7px 0}.passport small{font:10px monospace;color:#62777c}nav{display:flex;gap:5px;margin:10px 0 24px;border-bottom:1px solid #b6c6c5}nav button{padding:17px 20px;background:none;border:0;border-bottom:3px solid transparent;color:#4a6166;font-size:13px}nav button.active{color:#c7352d;border-bottom-color:#c7352d}nav span{font:11px monospace;margin-right:10px}nav b{background:#bcd5d9;padding:2px 6px;border-radius:3px}.board{display:grid;grid-template-columns:.85fr 1.15fr;gap:24px;align-items:stretch}.art{position:relative;min-height:590px;background-image:linear-gradient(180deg,#14293211 25%,#10262b 100%),var(--scene);background-size:cover;background-position:center;border-radius:3px;overflow:hidden;color:#fff}.stamp{position:absolute;top:24px;left:24px;background:#d13429;padding:8px 12px}.art-copy{position:absolute;bottom:32px;left:32px;right:32px}.art-copy h2{font-size:38px;letter-spacing:-1px;max-width:300px;margin:12px 0}.art-copy p{color:#e0f1f3;font-size:28px;margin:10px 0}.art-copy p span{font-size:13px}.art-copy small{font:10px monospace;color:#c1d9dd}.large-icon{font-size:54px;color:#f5e0b3}.appointment{padding:12px 0;border-bottom:1px solid #ffffff40;margin-bottom:14px;font-size:14px}.appointment b{margin-right:18px;color:#efad95}.conversation{background:#f8f8f1;padding:28px;border:1px solid #d3dcda;min-width:0}.section-title{display:flex;justify-content:space-between;gap:15px;color:#50686c}.signal{color:#cd352b}.start{min-height:470px;display:flex;flex-direction:column;justify-content:center;align-items:start}.speech-symbol{font-size:74px;color:#ce352c;line-height:1}.start h2{font-size:32px;letter-spacing:-1px;max-width:340px;margin:22px 0 0}.start small{font-size:10px;color:#607579;margin-top:15px}.primary{border:0;background:#c5352c;color:white;padding:16px 20px;font-size:13px;line-height:1.5;text-align:left}.user-bubble{margin:25px 0;padding:14px 18px;background:#e2eceb;border-radius:12px 12px 0 12px;font-size:13px}.response h2{font-size:32px;margin:18px 0 6px}.speaker{color:#a22f27}.romaji{font-family:monospace}.response p{margin:8px 0}.gentle{font-size:12px;color:#607579}.helpers{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.helpers button{padding:14px 8px;border:1px solid #b6c8ca;background:transparent;text-align:left}.helpers button.selected{background:#d9e7e6;border-color:#718e93}.helpers b{font-size:20px}.helpers span{display:block;font-size:10px;margin-top:6px;color:#50676b}.helper-answer{border-left:3px solid #d0342a;padding:12px 18px;background:#f0eee3;margin-top:18px}.helper-answer>span{font:10px monospace;color:#975246}.helper-answer p{margin:8px 0}.helper-answer h3{font-size:25px;margin:10px 0}.quest{border-top:1px solid #c5d3d1;margin-top:22px;padding-top:18px}.quest summary{cursor:pointer;font-size:13px;line-height:1.6}.quest label{display:block;font-size:11px;margin:12px 0}.input-row{display:flex;gap:8px}.input-row input{min-width:0;width:100%;border:1px solid #9bb4b8;background:#fff;padding:12px;font-size:13px}.success{color:#247050}.next{display:block;background:none;border:0;border-bottom:1px solid #c3342b;color:#a2322a;padding:12px 0;margin-top:15px;font-weight:bold;font-size:13px}.audio-message{font-size:12px}.memory{background-image:linear-gradient(180deg,#14293200,#10262b),url('/images/memory-quest.png')}.flashcard{min-height:380px;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;gap:12px}.flashcard h2{font-size:36px;margin:16px 0 0}.translation{padding:20px;border-top:1px solid #b6c8ca;width:100%;font-size:20px}.ratings{display:grid;grid-template-columns:1fr 1fr;gap:10px}.ratings button{background:#e0ece9;border:1px solid #b6c8ca;padding:16px 10px;font-size:13px}.ratings small{display:block;margin-top:8px;font-size:10px}footer{display:flex;justify-content:space-between;gap:20px;padding:26px 0;font:10px/1.6 monospace;color:#567176}footer a{color:#994138}@media(max-width:850px){.world{padding:0 20px}.intro{display:block}.passport{margin-top:25px}.badge{display:none}.board{grid-template-columns:1fr}.art{min-height:300px;background-position:center 45%}.art-copy{bottom:22px;left:24px}.art-copy h2{font-size:30px;max-width:none}.large-icon{display:none}.stamp{top:15px;left:20px}.start{min-height:340px}.conversation{padding:22px}nav button{padding:14px 8px;font-size:11px}nav span{margin-right:4px}footer{flex-direction:column}.flashcard h2{font-size:28px}.input-row{flex-wrap:wrap}.input-row .primary{width:100%}.art-copy p{font-size:24px}}
</style>
